/* Демо-режим AI-помощника для публичной версии без сервера.
   Когда /api/chat недоступен (статический хостинг), lesson.html берёт ответ отсюда:
   window.TSChatDemo.reply(вопрос, номерВопросаВДиалоге) → текст в той же мини-разметке,
   что и у настоящего помощника (```go, `код`, **жирный**, списки).
   Ответы заготовлены под урок Foreach и, как настоящий помощник, не решают задание целиком. */
(function () {
  // Правила проверяются по порядку, срабатывает первое подходящее
  var RULES = [
    {
      // студент прислал своё решение
      test: function (q) { return /func\s+ForEach/i.test(q); },
      answer: function (q) {
        var hasRange = /\brange\b/.test(q);
        var callsF = /\bf\s*\(/.test(q);
        if (hasRange && callsF) {
          return 'Выглядит хорошо 👍 Ты проходишь по срезу через `range` и вызываешь `f` для каждого элемента — это ровно то, что нужно.\n\n' +
            'Проверь себя:\n' +
            '- берёшь именно значение, а не индекс: `for _, v := range a`\n' +
            '- функция ничего не возвращает — `return` в конце не нужен\n' +
            '- пакет называется `piscine`, а файл — `foreach.go`\n\n' +
            'Запусти пример из раздела «Использование»: должно вывести `123456`.';
        }
        if (hasRange) {
          return 'Цикл уже есть — отлично. Но внутри него не видно вызова функции `f`.\n\n' +
            'Подсказка: `f` — это обычная переменная с функцией внутри. Её вызывают так же, как любую функцию: `f(значение)`. Какое значение нужно передать на каждом шаге?';
        }
        return 'Сигнатура верная, теперь нужно тело функции. Подсказка: чтобы что-то сделать с каждым элементом среза, нужен цикл.\n\n' +
          'Вспомни конструкцию `for ... range` — она по очереди отдаёт индекс и значение каждого элемента.';
      }
    },
    {
      // \b в JS не работает с кириллицей, поэтому границу слова задаём явно
      test: /^(привет|здравствуй\w*|хай|hello|hi)(?=[\s,.!?)]|$)/i,
      answer: 'Привет! Я помогу разобраться с квестом Foreach. Можешь спросить, как устроен `range`, что значит `f func(int)` в параметрах, или прислать свой код — подскажу, где ошибка.'
    },
    {
      test: /ошибк|не работает|не компил|panic|error|unused|declared and not used/i,
      answer: 'Пришли, пожалуйста, свой код и текст ошибки — посмотрю, в чём дело.\n\n' +
        'Самые частые ошибки в этом квесте:\n' +
        '- `declared and not used` — объявлен индекс из `range`, но не используется. Замени его на `_`.\n' +
        '- функция вызвана со скобками при передаче: `ForEach(PrintNbr(), a)` вместо `ForEach(PrintNbr, a)`.\n' +
        '- неверное имя пакета: в файле должно быть `package piscine`.'
    },
    {
      test: /реш|ответ|как сделать|с чего начать|подскаж|помоги|не понимаю|foreach/i,
      answer: 'Давай по шагам, без готового ответа 🙂\n\n' +
        '- **Что на входе:** функция `f` и срез `a`.\n' +
        '- **Что нужно:** для каждого числа из `a` вызвать `f(число)`.\n' +
        '- **Чем пройти по срезу:** циклом `for` с `range`.\n\n' +
        'Попробуй написать цикл, который просто печатает каждый элемент среза. Когда получится — замени печать на вызов `f`. Пришли код, если застрянешь.'
    },
    {
      test: /range|цикл|for\b|перебр|пройти/i,
      answer: '`range` перебирает срез и на каждом шаге отдаёт индекс и значение:\n\n' +
        '```go\nnums := []int{10, 20, 30}\nfor i, v := range nums {\n\tfmt.Println(i, v) // 0 10, 1 20, 2 30\n}\n```\n\n' +
        'Если индекс не нужен, его заменяют на `_`: `for _, v := range nums`. Иначе Go ругнётся на неиспользуемую переменную.'
    },
    {
      test: /func\s*\(\s*int\s*\)|функци\w* (как|в) (параметр|аргумент)|передать функцию|высшего порядка|callback|колбэк/i,
      answer: 'В Go функцию можно передать в другую функцию как обычное значение. Запись `f func(int)` значит: «параметр `f` — функция, которая принимает `int` и ничего не возвращает».\n\n' +
        '```go\nfunc twice(f func(int), n int) {\n\tf(n)\n\tf(n)\n}\n\ntwice(piscine.PrintNbr, 7) // напечатает 77\n```\n\n' +
        'Внутри `twice` мы просто вызываем `f(...)` — как любую другую функцию.'
    },
    {
      test: /срез|slice|массив|\[\]int/i,
      answer: 'Срез `[]int` — это список чисел, длину которого можно менять. Создают его так:\n\n' +
        '```go\na := []int{1, 2, 3}\nfmt.Println(len(a)) // 3\nfmt.Println(a[0])   // 1\n```\n\n' +
        'В квесте Foreach срез менять не нужно — только пройти по нему и для каждого элемента вызвать функцию.'
    },
    {
      test: /printnbr/i,
      answer: '`piscine.PrintNbr` печатает число без перевода строки — поэтому в примере все цифры идут подряд: `123456`.\n\n' +
        'В `ForEach` её передают как значение, **без скобок**: `ForEach(piscine.PrintNbr, a)`. Со скобками это был бы уже вызов, а не сама функция.'
    },
    {
      test: /запуст|go run|провер|тест/i,
      answer: 'Создай рядом `main.go` с примером из раздела «Использование» и запусти в терминале:\n\n' +
        '```go\n$ go run .\n123456\n```\n\n' +
        'Если вывод совпал — можно сдавать `foreach.go`.'
    }
  ];

  var FALLBACK = 'Это демо-версия помощника, поэтому отвечаю только на вопросы по уроку Foreach. Попробуй спросить:\n\n' +
    '- «Как работает range?»\n' +
    '- «Что значит f func(int)?»\n' +
    '- «С чего начать решение?»\n\n' +
    'Или пришли свой код функции `ForEach` — подскажу, что поправить.';

  window.TSChatDemo = {
    reply: function (question) {
      var q = String(question || '').trim();
      for (var i = 0; i < RULES.length; i++) {
        var r = RULES[i];
        var hit = typeof r.test === 'function' ? r.test(q) : r.test.test(q);
        if (hit) return typeof r.answer === 'function' ? r.answer(q) : r.answer;
      }
      return FALLBACK;
    }
  };
})();
